import React, { useEffect, useRef } from 'react';

const TechParticles = () => {
    const canvasRef = useRef(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d');

        // High-DPI / Retina Scaling for sharp lines
        const setupCanvas = () => {
            const dpr = window.devicePixelRatio || 1;
            canvas.width = canvas.offsetWidth * dpr;
            canvas.height = canvas.offsetHeight * dpr;
            ctx.scale(dpr, dpr);
        };

        setupCanvas();

        const particles = [];
        const particleCount = 35; // Optimized for performance

        class Particle {
            constructor() {
                this.x = Math.random() * (canvas.width / (window.devicePixelRatio || 1));
                this.y = Math.random() * (canvas.height / (window.devicePixelRatio || 1));
                this.size = Math.random() * 2 + 1;
                this.speedX = Math.random() * 0.6 - 0.3;
                this.speedY = Math.random() * 0.6 - 0.3;
                this.color = `rgba(6, 182, 212, ${Math.random() * 0.3 + 0.2})`;
            }

            update() {
                this.x += this.speedX;
                this.y += this.speedY;

                const width = canvas.width / (window.devicePixelRatio || 1);
                const height = canvas.height / (window.devicePixelRatio || 1);

                if (this.x > width) this.x = 0;
                if (this.x < 0) this.x = width;
                if (this.y > height) this.y = 0;
                if (this.y < 0) this.y = height;
            }

            draw() {
                ctx.fillStyle = this.color;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fill();
            }
        }

        class ArchLogo {
            constructor() {
                const width = canvas.width / (window.devicePixelRatio || 1);
                const height = canvas.height / (window.devicePixelRatio || 1);
                this.x = Math.random() * width;
                this.y = Math.random() * height;
                this.size = Math.random() * 25 + 20;
                this.speedX = Math.random() * 0.3 - 0.15;
                this.speedY = Math.random() * 0.3 - 0.15;
                this.rotation = Math.random() * Math.PI * 2;
                this.rotationSpeed = (Math.random() - 0.5) * 0.008;
            }

            update() {
                this.x += this.speedX;
                this.y += this.speedY;
                this.rotation += this.rotationSpeed;

                const width = canvas.width / (window.devicePixelRatio || 1);
                const height = canvas.height / (window.devicePixelRatio || 1);

                if (this.x > width + 50) this.x = -50;
                if (this.x < -50) this.x = width + 50;
                if (this.y > height + 50) this.y = -50;
                if (this.y < -50) this.y = height + 50;
            }

            draw() {
                ctx.save();
                ctx.translate(this.x, this.y);
                ctx.rotate(this.rotation);

                ctx.strokeStyle = 'rgba(23, 147, 209, 0.4)';
                ctx.fillStyle = 'rgba(23, 147, 209, 0.05)';
                ctx.lineWidth = 1.5;
                ctx.lineJoin = 'round';

                const h = this.size;
                const w = this.size * 1.1;

                ctx.beginPath();
                ctx.moveTo(0, -h / 2); // Top peak
                ctx.lineTo(w / 2, h / 2); // Right flare
                ctx.bezierCurveTo(w / 4, h / 3.5, -w / 4, h / 3.5, -w / 2, h / 2); // Concave base
                ctx.closePath();
                ctx.fill();
                ctx.stroke();

                // Internal Swoosh
                ctx.beginPath();
                ctx.moveTo(-w / 6, h / 10);
                ctx.bezierCurveTo(0, -h / 8, w / 3, 0, w / 4, h / 4);
                ctx.stroke();

                ctx.restore();
            }
        }

        for (let i = 0; i < particleCount; i++) {
            particles.push(new Particle());
        }

        for (let i = 0; i < 10; i++) {
            particles.push(new ArchLogo());
        }

        function connectParticles() {
            for (let i = 0; i < particleCount; i++) {
                for (let j = i + 1; j < particleCount; j++) {
                    const dx = particles[i].x - particles[j].x;
                    const dy = particles[i].y - particles[j].y;
                    const distance = Math.sqrt(dx * dx + dy * dy);

                    if (distance < 120) {
                        ctx.strokeStyle = `rgba(6, 182, 212, ${0.15 * (1 - distance / 120)})`;
                        ctx.lineWidth = 1;
                        ctx.beginPath();
                        ctx.moveTo(particles[i].x, particles[i].y);
                        ctx.lineTo(particles[j].x, particles[j].y);
                        ctx.stroke();
                    }
                }
            }
        }

        function animate() {
            const width = canvas.width / (window.devicePixelRatio || 1);
            const height = canvas.height / (window.devicePixelRatio || 1);
            ctx.clearRect(0, 0, width, height);

            particles.forEach(p => {
                p.update();
                p.draw();
            });

            connectParticles();
            requestAnimationFrame(animate);
        }

        animate();

        const handleResize = () => {
            setupCanvas();
        };

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    return (
        <canvas
            ref={canvasRef}
            className="w-full h-full absolute top-0 left-0"
            style={{ opacity: 0.5 }}
        />
    );
};

export default TechParticles;
